css:
:root{--ivory:#FBF7F2;--cream:#F5ECE3;--blush:#F3DFDA;--blush-d:#E8C7C0;--rose:#C98A8E;--rose-d:#B06C72;--gold:#C9A66B;--gold-d:#A8854B;--gold-l:#E9D7B4;--champ:#F1E6D2;
--plum:#2E2233;--plum-2:#453549;--ink:#2B2430;--muted:#6B5F70;--taupe:#9A8F9C;--paper:#fff;
--line:rgba(46,34,51,.12);--line-soft:rgba(46,34,51,.07);--shadow:0 30px 70px rgba(46,34,51,.14);--shadow-sm:0 14px 36px rgba(46,34,51,.08);
--serif:"Cormorant Garamond","Playfair Display",Georgia,serif;--sans:"Montserrat",-apple-system,"Segoe UI",Helvetica,Arial,sans-serif;--script:"Great Vibes","Dancing Script",cursive;
--gut:40px;--maxw:1240px}
@media(max-width:768px){:root{--gut:26px}}@media(max-width:430px){:root{--gut:20px}}
*{box-sizing:border-box}html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;font-family:var(--sans);color:var(--ink);background:var(--ivory);line-height:1.7;font-size:15.5px;font-weight:400}
img{max-width:100%;height:auto;display:block}a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--serif);font-weight:600;line-height:1.08;margin:0 0 .5em;letter-spacing:.005em}
h2{font-size:clamp(34px,4.4vw,54px)}h3{font-size:24px}p{margin:0 0 1em}
.wrap{max-width:var(--maxw);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.rv{animation:rvIn .9s both}@keyframes blink{to{opacity:0}}@keyframes rvIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
.eyebrow{display:inline-flex;align-items:center;gap:12px;font-size:11px;letter-spacing:.28em;text-transform:uppercase;font-weight:600;color:var(--gold-d);margin-bottom:16px}
.eyebrow::before,.eyebrow::after{content:"";width:28px;height:1px;background:var(--gold)}
.eyebrow.left::before{display:none}
.lead{font-size:17px;color:var(--muted);max-width:640px;font-weight:400}
.on-plum{color:#fff}.on-plum .lead,.on-plum p{color:rgba(255,255,255,.8)}.on-plum .eyebrow{color:var(--gold-l)}.on-plum .eyebrow::before,.on-plum .eyebrow::after{background:var(--gold)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:15px 30px;border-radius:999px;font-weight:600;font-size:12px;letter-spacing:.16em;text-transform:uppercase;border:1.5px solid transparent;transition:transform .2s,box-shadow .2s,background .2s;white-space:nowrap;cursor:pointer;font-family:var(--sans)}
.btn:hover{transform:translateY(-2px)}
@media(max-width:380px){.btn{padding:14px 18px;letter-spacing:.1em;white-space:normal;text-align:center;max-width:100%}.ctas{flex-direction:column;align-items:stretch}}
.btn-gold{background:linear-gradient(135deg,#D9B978,#C9A66B 50%,#B9924F);color:var(--plum);box-shadow:0 14px 30px rgba(201,166,107,.35)}
.btn-plum{background:var(--plum);color:#fff;box-shadow:0 14px 30px rgba(46,34,51,.22)}
.btn-ghost{border-color:var(--gold);color:var(--plum);background:transparent}
.btn-ghost-w{border-color:rgba(255,255,255,.5);color:#fff;background:transparent}
.btn-rose{background:var(--rose);color:#fff;box-shadow:0 14px 30px rgba(201,138,142,.35)}
.chip{display:inline-block;padding:8px 16px;border-radius:999px;font-size:11px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;border:1px solid var(--gold-l);background:#fff;color:var(--plum);margin:0 8px 8px 0}
.chip:hover{border-color:var(--gold)}
.rule{height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent)}
/* top strip */
.util{background:var(--plum);color:var(--gold-l);font-size:11px;font-weight:500;letter-spacing:.14em;text-transform:uppercase}
.util .wrap{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:34px}
.util span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.util a{white-space:nowrap}.util a+a{margin-left:18px}.util .u-r a:last-child{color:#fff;border-bottom:1px solid var(--gold)}
@media(max-width:760px){.util .u-l,.util .u-msg{display:none}.util .wrap{justify-content:center}}
/* header – centred, boutique style */
header{position:sticky;top:0;z-index:50;background:rgba(251,247,242,.96);backdrop-filter:blur(8px);border-bottom:1px solid var(--line-soft)}
.hdr{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;min-height:92px;gap:16px}
.hdr .h-l{display:flex;align-items:center;gap:18px;font-size:12px;letter-spacing:.08em;color:var(--muted)}
.hdr .h-r{display:flex;align-items:center;justify-content:flex-end;gap:14px}
.logo{display:flex;flex-direction:column;align-items:center;line-height:1;color:var(--plum);text-align:center}
.logo .w{font-family:var(--serif);font-weight:600;font-size:26px;letter-spacing:.3em;text-transform:uppercase;padding-left:.3em}
.logo .s{font-family:var(--script);font-size:30px;color:var(--gold-d);margin-top:-6px}
.logo img{height:64px;width:auto}
footer .logo img{height:60px}
.navbar{border-top:1px solid var(--line-soft)}
.nav{display:flex;justify-content:center;align-items:center;gap:2px;flex-wrap:wrap}
.nav>a{padding:14px 15px;font-size:11.5px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;white-space:nowrap;position:relative}
.nav>a::after{content:"";position:absolute;left:15px;right:15px;bottom:9px;height:1px;background:var(--gold);transform:scaleX(0);transition:.25s}
.nav>a:hover::after,.nav>a.active::after{transform:scaleX(1)}
.burger-in,.nav-toggle,.m-only{display:none}
@media(min-width:1101px){.hdr .nav{display:none}}
@media(max-width:1100px){.navbar{display:none}}
@media(max-width:1100px){
 .hdr{grid-template-columns:44px 1fr 44px;min-height:78px}
 .hdr .h-l,.hdr .h-r .btn,.hdr .h-r .hp{display:none}
 .logo .w{font-size:21px}.logo .s{font-size:26px}.logo img{height:50px}
 .navbar{border:0}
 .nav{position:fixed;top:0;right:0;height:100vh;width:min(360px,92vw);background:var(--ivory);flex-direction:column;align-items:stretch;justify-content:flex-start;gap:0;padding:96px 28px 40px;margin:0;box-shadow:var(--shadow);clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .35s;overflow-y:auto;z-index:55;flex-wrap:nowrap}
 .nav>a{padding:15px 4px;border-bottom:1px solid var(--line-soft);font-size:12px}
 .nav>a::after{display:none}
 .nav .m-only{display:flex;margin-top:18px;border:0}
 .nav-toggle{display:flex;flex-direction:column;justify-content:center;gap:5px;width:44px;height:44px;cursor:pointer;z-index:60;position:relative;grid-column:3}
 .nav-toggle i{display:block;height:1.5px;background:var(--plum);border-radius:2px;transition:.3s}
 .burger-in:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
 .burger-in:checked ~ .nav-toggle i:nth-child(1){transform:translateY(6.5px) rotate(45deg)}
 .burger-in:checked ~ .nav-toggle i:nth-child(2){opacity:0}
 .burger-in:checked ~ .nav-toggle i:nth-child(3){transform:translateY(-6.5px) rotate(-45deg)}
 .hdr .logo{grid-column:2}
}
/* hero */
.hero{position:relative;overflow:hidden;background:#F6EEE6 center center/cover no-repeat;min-height:0;aspect-ratio:2038/771}
.hero::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(251,247,242,.9) 0%,rgba(251,247,242,.82) 28%,rgba(251,247,242,.3) 40%,rgba(251,247,242,0) 48%)}
.hero-grid{display:grid;grid-template-columns:minmax(0,.78fr) minmax(0,1.22fr);gap:40px;align-items:center;padding-top:40px;padding-bottom:40px;position:absolute;inset:0;height:100%}
.hero h1{font-size:clamp(30px,3.1vw,50px);margin-bottom:2px;font-weight:500;line-height:1.05}
.hero h1 em{font-style:italic;font-weight:500;color:var(--gold-d)}
.script{font-family:var(--script);font-size:clamp(24px,2.4vw,36px);color:var(--rose-d);line-height:1.1;margin:0 0 8px;font-weight:400}
.hero .lead{margin-bottom:16px;max-width:460px;font-size:clamp(13px,1.05vw,16px);line-height:1.5}
.pill{display:inline-flex;max-width:100%;text-align:left;align-items:center;gap:10px;padding:6px 14px;border-radius:999px;background:#fff;border:1px solid var(--gold-l);color:var(--gold-d);font-size:11px;letter-spacing:.24em;text-transform:uppercase;font-weight:600;margin-bottom:24px;box-shadow:var(--shadow-sm)}
.pill i{width:7px;height:7px;border-radius:50%;background:var(--gold);box-shadow:0 0 8px var(--gold)}
.hero .pill{margin-bottom:12px;font-size:10px}
.hero .ctas{margin-bottom:0}
.hero .ctas .btn{padding:12px 22px;font-size:11px}
.ctas{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:22px}
.ticks{display:flex;flex-wrap:wrap;gap:8px 22px;font-size:13px;color:var(--muted);margin:0 0 12px}
.hero-strip{background:var(--ivory);padding:26px 0 30px;border-bottom:1px solid var(--line-soft)}
.hs-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:28px;align-items:center}
.hs-grid .mini{margin:0;max-width:none}
@media(max-width:980px){.hs-grid{grid-template-columns:1fr}}
.ticks span::before{content:"\2713";color:var(--gold-d);font-weight:700;margin-right:7px}
.hero-mobile{display:none}
@media(max-width:980px){.hero{background:var(--ivory)!important;min-height:0;padding-top:0;aspect-ratio:auto}.hero-grid{position:relative;inset:auto;height:auto}.hero::before{display:none}.hero-grid{grid-template-columns:1fr;padding-top:0;padding-bottom:44px;gap:26px}.hero-grid .rv{padding-top:0}.hero .wrap.hero-grid{padding-top:0}.hero-mobile{display:block;margin:0 calc(var(--gut)*-1);line-height:0}.hero-mobile img{width:100%;height:auto;display:block}}
/* hero mini form */
.mini{margin-top:0;background:#fff;border:1px solid var(--gold-l);border-radius:18px;padding:18px;box-shadow:var(--shadow-sm);max-width:620px}
.mini form{display:grid;grid-template-columns:1.2fr 1fr 1fr auto;gap:10px;align-items:end}
.mini label{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--taupe);font-weight:600;display:block;margin-bottom:4px}
.mini input{width:100%;min-width:0;padding:12px 12px;border:1px solid var(--line);border-radius:10px;background:var(--ivory);font:inherit;font-size:14px;color:var(--ink)}
.mini .btn{padding:14px 20px}
.mini .f{min-width:0}
@media(max-width:1180px){.mini form{grid-template-columns:1fr 1fr}.mini .btn{grid-column:span 2}}
@media(max-width:480px){.mini form{grid-template-columns:1fr}.mini .btn{grid-column:auto}}
/* marquee letters (pure CSS) – ivory face, gold frame, warm bulbs */
.mq-row{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.mq{--s:106px;width:var(--s);height:calc(var(--s)*1.32);border-radius:8px;background:linear-gradient(180deg,#FFFFFF,#F7F2EC);border:1px solid #E2D6C9;box-shadow:0 0 0 4px #FFFFFF,0 0 0 5px #E2D6C9,0 26px 50px rgba(46,34,51,.18),inset 0 0 34px rgba(255,205,130,.22);display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden;flex:0 0 auto}
.mq::before{content:"";position:absolute;inset:6px;border-radius:5px;border:1px solid rgba(201,166,107,.22)}
.mq b{font-family:"Montserrat",Arial,sans-serif;font-weight:800;font-size:calc(var(--s)*.86);line-height:1;background:radial-gradient(circle closest-side,#FFFFFF 0 34%,#F4F8FF 50%,rgba(220,232,255,.8) 64%,transparent 82%) 0 0/calc(var(--s)*.11) calc(var(--s)*.11),#C9BDB0;-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 3px rgba(255,255,255,1)) drop-shadow(0 0 12px rgba(200,220,255,.7))}
.mq-sm{--s:60px;border-radius:6px;box-shadow:0 0 0 3px #FDFBF8,0 0 0 4px #EADFD3,0 10px 24px rgba(46,34,51,.10)}
@media(max-width:980px){.mq{--s:84px}}
@media(max-width:430px){.mq{--s:64px;box-shadow:0 0 0 3px #FDFBF8,0 0 0 4px #EADFD3,0 14px 30px rgba(46,34,51,.12)}.mq-row{gap:8px}}
/* sections */
section{padding:88px 0;scroll-margin-top:150px}
@media(max-width:768px){section{padding:62px 0}}
.center{text-align:center}.center .lead{margin-left:auto;margin-right:auto}
.sec-head{max-width:760px;margin:0 auto 46px;text-align:center}
.zone-white{background:#fff}.zone-cream{background:var(--cream)}.zone-blush{background:linear-gradient(180deg,#FBF7F2,#F3DFDA)}.zone-plum{background:radial-gradient(circle at 15% 20%,rgba(201,166,107,.18),transparent 35%),radial-gradient(circle at 85% 85%,rgba(201,138,142,.25),transparent 35%),var(--plum);color:#fff}
.grid{display:grid;gap:20px}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}.g4{grid-template-columns:repeat(4,minmax(0,1fr))}.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
@media(max-width:1024px){.g4{grid-template-columns:repeat(2,minmax(0,1fr))}.g3{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.g4,.g3,.g2{grid-template-columns:1fr}}
.grid>*{min-width:0}
/* category cards */
.ccard{background:#fff;border-radius:18px;overflow:hidden;border:1px solid var(--line-soft);box-shadow:var(--shadow-sm);display:flex;flex-direction:column;transition:transform .25s,box-shadow .25s}
.ccard:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.ccard img{aspect-ratio:4/3;object-fit:cover;width:100%}
.ccard .body{padding:22px 24px 24px;display:flex;flex-direction:column;gap:6px;flex:1}
.ccard h3{margin:0;font-size:26px}.ccard p{color:var(--muted);font-size:14px;margin:0}
.ccard .more{margin-top:auto;padding-top:12px;font-size:11px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:var(--gold-d)}
.ccard .price{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--rose-d);font-weight:600}
.ccard.cta{background:var(--plum);color:#fff;border:0;justify-content:center;padding:34px 28px;text-align:center}
.ccard.cta h3{font-size:30px}.ccard.cta p{color:rgba(255,255,255,.78)}.ccard.cta .btn{margin:16px auto 0}
/* occasion cards */
.ocard{background:#fff;border-radius:16px;border:1px solid var(--line-soft);box-shadow:var(--shadow-sm);display:flex;flex-direction:column;position:relative;overflow:hidden;transition:transform .25s,box-shadow .25s}.ocard:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.ocard>img{aspect-ratio:4/3;object-fit:cover;width:100%}.ocard .body{padding:22px 24px 24px;display:flex;flex-direction:column;gap:8px;flex:1}
.ocard::before{content:"";position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,var(--gold),var(--rose))}
.ocard .ic{width:46px;height:46px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:18px;background:var(--blush);color:var(--rose-d);margin-top:-45px;border:3px solid #fff;position:relative}
.ocard h3{font-size:24px;margin:8px 0 0}.ocard p{color:var(--muted);font-size:14px;margin:0}
.ocard .more{margin-top:auto;padding-top:10px;font-size:11px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:var(--gold-d)}
/* catalogue */
.cat-block{margin-bottom:40px}
.cat-head{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:16px;border-bottom:1px solid var(--line-soft);padding-bottom:10px}
.cat-head h3{font-size:28px;margin:0}
.cat-head .meta{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:600}
.cat-head .meta b{color:var(--rose-d)}
.cat-row{display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:10px}
.item{background:#F8EFEA;border:1px solid var(--line-soft);border-radius:12px;padding:12px 8px 10px;display:flex;flex-direction:column;align-items:center;gap:8px;transition:border-color .2s,transform .2s}
.item:hover{border-color:var(--gold);transform:translateY(-2px)}
.item img{width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:8px}
.item small{font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:600;text-align:center;line-height:1.3}
.item small b{display:block;color:var(--plum);font-weight:600}
.stat{display:flex;flex-wrap:wrap;gap:14px;justify-content:center;margin-top:12px}
.stat div{background:#fff;border:1px solid var(--gold-l);border-radius:14px;padding:16px 24px;min-width:150px;text-align:center}
.stat b{display:block;font-family:var(--serif);font-size:38px;color:var(--gold-d);line-height:1;font-weight:600}.stat span{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);font-weight:600}
/* specials */
.sp{background:#fff;border-radius:18px;border:1px solid var(--gold-l);box-shadow:var(--shadow-sm);padding:28px 26px 26px;display:flex;flex-direction:column;gap:8px;position:relative}
.sp .tag{position:absolute;top:-13px;left:22px;background:var(--rose);color:#fff;font-size:10px;letter-spacing:.18em;text-transform:uppercase;font-weight:600;padding:6px 12px;border-radius:999px}
.sp h3{font-size:26px;margin:6px 0 0}.sp p{color:var(--muted);font-size:14px;margin:0}
.sp .save{font-family:var(--serif);font-size:44px;color:var(--gold-d);line-height:1;font-weight:600}
.sp .save small{font-family:var(--sans);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:600;display:block;margin-top:4px}
.sp .btn{margin-top:auto;align-self:flex-start}
.sp .code{font-size:12px;color:var(--muted)}.sp .code b{color:var(--plum);letter-spacing:.14em}
/* packages */
.pack{background:#fff;border-radius:18px;border:1px solid var(--line-soft);box-shadow:var(--shadow-sm);overflow:hidden;display:flex;flex-direction:column}
.pack .top{background:linear-gradient(180deg,#EFD6D0,#F3E3DC);display:flex;justify-content:center;align-items:center}.pack .top img{width:100%;aspect-ratio:4/3;object-fit:cover}.pack .top .mq-row{padding:28px 14px}
.pack .top .mq-sm{--s:46px}
.pack .body{padding:20px 24px 26px;display:flex;flex-direction:column;gap:8px;flex:1}
.pack h3{font-size:26px;margin:0}.pack p{font-size:14px;color:var(--muted);margin:0}
.pack .from{font-family:var(--serif);font-size:26px;color:var(--plum);margin-top:auto;font-weight:600}.pack .from small{font-family:var(--sans);font-size:11px;color:var(--taupe);letter-spacing:.12em;text-transform:uppercase;font-weight:600}
.pack .btn{margin-top:14px}
.tag{display:inline-block;font-size:10px;letter-spacing:.18em;text-transform:uppercase;font-weight:600;padding:5px 12px;border-radius:999px;background:var(--champ);color:var(--gold-d);align-self:flex-start}
/* steps */
.steps{counter-reset:s}
.step{position:relative;padding:34px 24px 26px;background:#fff;border-radius:16px;border:1px solid var(--line-soft);box-shadow:var(--shadow-sm)}
.step::before{counter-increment:s;content:counter(s);position:absolute;top:-18px;left:22px;width:38px;height:38px;border-radius:50%;background:var(--plum);color:var(--gold-l);font-family:var(--serif);font-weight:600;display:flex;align-items:center;justify-content:center;font-size:17px;border:3px solid var(--ivory)}
.step h3{font-size:22px;margin-top:4px}.step p{font-size:14px;color:var(--muted);margin:0}
/* gallery */
.gal{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:230px;gap:14px}
.gal a{position:relative;border-radius:14px;overflow:hidden;border:4px solid #fff;box-shadow:var(--shadow-sm)}
.gal img{width:100%;height:100%;object-fit:cover}
.gal a span{position:absolute;left:14px;bottom:12px;font-family:var(--serif);font-size:17px;color:var(--plum);background:rgba(255,255,255,.85);padding:4px 10px;border-radius:6px}
.gal .wide{grid-column:span 2}
@media(max-width:900px){.gal{grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-rows:200px}}
@media(max-width:480px){.gal{grid-template-columns:1fr;grid-auto-rows:210px}.gal .wide{grid-column:span 1}}
/* why */
.why{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:56px;align-items:center}
.why ul{list-style:none;padding:0;margin:0;display:grid;gap:14px}
.why li{display:flex;gap:16px;align-items:flex-start;background:#fff;border:1px solid var(--line-soft);border-radius:14px;padding:18px 20px;box-shadow:var(--shadow-sm)}
.why li b{display:block;font-family:var(--serif);font-size:21px;font-weight:600}
.why li span{font-size:14px;color:var(--muted)}
.why li i{flex:0 0 42px;height:42px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:var(--blush);font-style:normal;color:var(--rose-d)}
.badge{display:flex;width:max-content;max-width:100%;align-items:center;gap:12px;background:#fff;border:1px solid var(--gold-l);padding:14px 20px;border-radius:14px;margin-bottom:22px}
