footer .logo{align-items:flex-start;color:#fff;margin-bottom:10px}footer .logo .s{color:var(--gold-l)}
footer .script{font-size:26px;color:var(--gold-l);margin:0 0 12px}
footer h4{font-family:var(--sans);font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:var(--gold-l);margin-bottom:14px}
