/* sticky side tab (desktop) */
.side-tab{position:fixed;right:0;top:50%;transform:translateY(-50%) rotate(180deg);writing-mode:vertical-rl;background:var(--plum);color:var(--gold-l);padding:18px 12px;border-radius:0 10px 10px 0;font-size:11px;letter-spacing:.26em;text-transform:uppercase;font-weight:600;z-index:45;box-shadow:-8px 0 24px rgba(46,34,51,.2);border:1px solid var(--gold-d);border-right:0}
.side-tab:hover{color:#fff}
@media(max-width:900px){.side-tab{display:none}}
/* sticky mobile bar */
.mbar{display:none}
