/* welcome pop-up (pure CSS: checkbox checked on load; label closes) */
.pop-in{display:none}
.pop{position:fixed;inset:0;z-index:70;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(46,34,51,.55);backdrop-filter:blur(3px);animation:popIn .6s 1.8s both}
@keyframes popIn{from{opacity:0;visibility:hidden}to{opacity:1;visibility:visible}}
.pop-in:not(:checked) ~ .pop{display:none}
.pop-box{position:relative;background:var(--ivory);border-radius:22px;max-width:760px;width:100%;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);overflow:hidden;box-shadow:0 40px 90px rgba(0,0,0,.35);border:1px solid var(--gold-l)}
.pop-box .img{background:linear-gradient(180deg,#EFD6D0,#F1E3D1);display:flex;align-items:center;justify-content:center;padding:28px}
.pop-box .img .mq{--s:56px}
.pop-box .txt{padding:36px 34px 30px}
.pop-box h3{font-size:32px;margin-bottom:6px;font-weight:500}.pop-box h3 em{font-style:italic;color:var(--gold-d)}
.pop-box p{font-size:14px;color:var(--muted)}
.pop-box form{display:grid;gap:10px;margin-top:14px}
.pop-box input{width:100%;min-width:0;padding:12px 14px;border:1px solid var(--line);border-radius:10px;background:#fff;font:inherit;font-size:14px}
.pop-close{position:absolute;top:12px;right:14px;width:36px;height:36px;border-radius:50%;background:#fff;border:1px solid var(--line);display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:18px;color:var(--plum);z-index:2}
