@media(max-width:640px){.pop-box{grid-template-columns:1fr}.pop-box .img{padding:18px}.pop-box .img .mq{--s:48px}.pop-box .txt{padding:26px 22px 22px}}

.fgrid{grid-template-columns:1.6fr 1fr 1fr}@media(max-width:900px){.fgrid{grid-template-columns:1fr 1fr}}@media(max-width:520px){.fgrid{grid-template-columns:1fr}}a.ilink{color:var(--gold-d);text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px;font-weight:600;cursor:pointer}a.ilink:hover{color:var(--plum);text-decoration-thickness:2px}.on-plum a.ilink,.zone-plum a.ilink{color:var(--gold)}.on-plum a.ilink:hover{color:#fff}
.byline{font-size:13px;color:var(--muted);margin:10px 0 0}.mapbox{border:0;width:100%;height:380px;border-radius:14px;box-shadow:var(--shadow-sm);display:block}.pfaq{max-width:820px;margin:0 auto}

main img{max-width:100%;height:auto}.enq>*{min-width:0}.enq>a img{width:100%;height:auto;border-radius:18px;border:6px solid #fff;box-shadow:var(--shadow)}.why>*{min-width:0}.grid>*{min-width:0}.grid>img{width:100%;border-radius:14px;box-shadow:var(--shadow-sm)}.mq img{width:100%;height:100%;object-fit:contain;display:block}.side-tab,.mbar{z-index:60}
.subhero{background:linear-gradient(90deg,#FBF7F2 0%,#F3DFDA 100%)}
.sub-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:40px;align-items:center;padding-top:56px;padding-bottom:56px}
.subhero h1{font-size:clamp(34px,4vw,54px);font-weight:500;line-height:1.05}.subhero .lead{margin:14px 0 22px}.subhero .ticks{margin-top:14px}
