@media(max-width:900px){.sub-grid{grid-template-columns:1fr;padding-top:36px;padding-bottom:36px}}
.card{background:#fff;border-radius:14px;border:1px solid var(--line-soft);box-shadow:var(--shadow-sm);padding:22px;min-width:0}.card h3{font-size:20px;margin:0 0 6px}.card p{color:var(--muted);font-size:14px;margin:0}
.rel{background:#fff;border-radius:14px;border:1px solid var(--line-soft);box-shadow:var(--shadow-sm);padding:22px;display:flex;flex-direction:column;gap:6px;border-top:4px solid var(--gold);min-width:0}
.rel h3{font-size:19px;margin:0}.rel p{color:var(--muted);font-size:14px;margin:0}.rel .more{margin-top:auto;font-size:11px;font-weight:600;letter-spacing:.18em;text-transform:uppercase;color:var(--gold-d)}
