/* ===== AFTER-DARK SKIN ===== */
:root{--night:#1D1522;--night-2:#2A1F30;--candle:#F7E4B4}
h1,h2,h3,h4{font-weight:500}
main h2{font-weight:400;letter-spacing:-.005em}
.eyebrow{text-transform:none;font-family:var(--serif);font-style:italic;font-size:21px;letter-spacing:.01em;font-weight:500;color:var(--gold-d);margin-bottom:6px;gap:0}
.eyebrow::before,.eyebrow::after{display:none}
.btn{letter-spacing:.14em}

/* ---- home hero: full-height evening photograph, words set low on the left ---- */
.hero{background-color:var(--night)}
.hero h1{color:#FFFDF8;font-weight:300;letter-spacing:-.01em}
.hero .script{color:var(--candle)}
.hero .lead{color:rgba(255,253,248,.82)}
.hero .pill{background:rgba(255,255,255,.06);border-color:rgba(233,215,180,.55);color:var(--candle);box-shadow:none;backdrop-filter:blur(6px)}
.hero .btn-ghost,.subhero .btn-ghost,#builder .btn-ghost,#quote .btn-ghost{border-color:rgba(233,215,180,.75);color:#FFFDF8}
@media(min-width:981px) and (max-width:1279px){
.hero{background-image:none!important;aspect-ratio:auto;min-height:0}
.hero::before{display:none}
.hero .wrap.hero-grid{position:relative;inset:auto;height:auto;min-height:0;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);align-items:center;gap:44px;padding-top:48px;padding-bottom:124px;padding-right:max(var(--gut,40px),58px)}
.hero-grid>div:last-child:empty{display:none}
.hero .hero-grid>.rv{grid-column:1;grid-row:1}
.hero .hero-grid>.hero-mobile{grid-column:2!important;grid-row:1;width:auto;max-width:100%;margin:0}
.hero-mobile{display:block;order:2;margin:0;line-height:0;border-radius:4px;box-shadow:0 0 0 1px rgba(233,215,180,.5),0 0 0 10px rgba(233,215,180,.07),0 50px 110px rgba(0,0,0,.55),0 0 120px rgba(255,214,140,.2)}
.hero-mobile img{width:100%;height:auto;display:block;border-radius:4px}
.hero h1{font-size:clamp(42px,4.3vw,68px);line-height:1;margin-bottom:10px}
.hero .script{font-size:clamp(28px,2.6vw,42px);margin-bottom:14px}
.hero .lead{font-size:16px;max-width:500px;line-height:1.65;margin-bottom:24px}
.hero .ctas .btn{padding:16px 30px;font-size:12px}
}
@media(min-width:1280px){
.hero{aspect-ratio:auto;min-height:0;height:max(520px,37.83vw);max-width:100%;background-size:cover;background-position:100% 50%}
.hero::before{background:linear-gradient(90deg,rgba(24,16,29,.97) 0%,rgba(24,16,29,.93) 27%,rgba(24,16,29,.5) 35.5%,rgba(24,16,29,0) 42%),linear-gradient(0deg,rgba(24,16,29,.55) 0%,rgba(24,16,29,0) 22%)}
.hero .wrap.hero-grid{align-items:center;grid-template-columns:minmax(0,420px) minmax(0,1fr);padding-top:26px;padding-bottom:64px}
.hero h1{font-size:clamp(40px,3.5vw,58px);line-height:1;margin-bottom:8px}
.hero .script{font-size:clamp(26px,2.3vw,38px);margin-bottom:10px}
.hero .lead{font-size:clamp(14px,1.05vw,16px);max-width:min(440px,30vw);line-height:1.55;margin-bottom:18px;text-shadow:0 1px 12px rgba(24,16,29,.9)}
.hero .pill{display:none}
.hero .ctas .btn{padding:14px 24px;font-size:11.5px}
.hero-strip{margin-top:-30px}
}
@media(max-width:980px){
.hero{background:var(--night)!important}
.hero-grid{padding-bottom:96px}
.hero-mobile::before{content:"";position:absolute;left:0;right:0;bottom:-1px;height:46%;background:linear-gradient(0deg,var(--night),rgba(29,21,34,0));z-index:1;pointer-events:none}
.hero h1{font-size:clamp(38px,10.5vw,56px);line-height:1}
.hero .rv{margin-top:-34px;position:relative;z-index:2}
.hero .lead{font-size:15px;max-width:none}
}

/* ---- the booking bar: sits across the bottom edge of the hero ---- */
.hero-strip{background:transparent;border:0;padding:0 0 30px;margin-top:-78px;position:relative;z-index:4}
.hs-grid{grid-template-columns:1fr;gap:26px}
.hero-strip .mini{order:-1;max-width:none;border-radius:6px;padding:22px 26px 24px;border:1px solid var(--gold-l);box-shadow:0 44px 90px rgba(24,16,29,.34),0 0 0 6px rgba(255,255,255,.5)}
.hero-strip .mini form{grid-template-columns:1.5fr 1fr 1fr auto;gap:14px}
.hero-strip .mini label{text-transform:none;font-family:var(--serif);font-style:italic;font-size:17px;letter-spacing:0;color:var(--plum);font-weight:500;margin-bottom:6px}
.hero-strip .mini input{border-radius:2px;border:0;border-bottom:1px solid var(--gold);background:transparent;padding:10px 2px;font-size:15px}
.hero-strip .mini input:focus{outline:0;border-bottom-color:var(--plum);box-shadow:0 1px 0 var(--plum)}
.hero-strip .mini .btn{padding:16px 30px}
.hero-strip .hs-grid>div:first-child{text-align:center}
.hero-strip .ticks{justify-content:center;margin-bottom:16px}
.hero-strip .chip{border-radius:2px;background:transparent}
@media(max-width:980px){.hero-strip{margin-top:-64px}.hero-strip .mini form{grid-template-columns:1fr 1fr}.hero-strip .mini{padding:18px}}
@media(max-width:520px){.hero-strip .mini form{grid-template-columns:1fr}}
.hero-strip+.rule{display:none}

/* ---- figures: one quiet hairline row ---- */
#glance{padding-top:26px}
.glance{background:none;border:0;border-top:1px solid var(--gold-l);border-bottom:1px solid var(--gold-l);border-radius:0;box-shadow:none;padding:30px 0}
.glance b{font-size:clamp(34px,3.8vw,54px);font-weight:400;color:var(--plum)}
@media(min-width:981px){.glance div+div{border-left:1px solid var(--line)}}

/* ---- evening sections ---- */
#builder,#quote{background:radial-gradient(ellipse at 82% 18%,rgba(201,166,107,.22),transparent 46%),radial-gradient(ellipse at 8% 92%,rgba(201,138,142,.18),transparent 44%),var(--night);color:#FFFDF8}
#builder h2,#quote h2{color:#FFFDF8}
#builder .lead,#quote .lead,#builder p,#quote .enq>div:first-child p,#quote ul{color:rgba(255,253,248,.8)}
#builder .eyebrow,#quote .eyebrow{color:var(--candle)}
#builder a.ilink,#quote .enq>div:first-child a.ilink,.subhero a.ilink{color:var(--candle)}
#quote .enq ul li::before{color:var(--candle)}
#quote .qcard{border-radius:6px;color:var(--ink);box-shadow:0 44px 90px rgba(0,0,0,.4),0 0 0 6px rgba(255,255,255,.08)}
#quote .qcard p,#quote .qcard .fine{color:var(--muted)}

/* ---- photo frames: a fine gold line and a glow; the photo itself is never cropped ---- */
.ccard{background:none;border:0;box-shadow:none;border-radius:0;overflow:visible;text-align:center}
.ccard img{aspect-ratio:auto;height:auto;border-radius:4px;box-shadow:0 30px 60px rgba(46,34,51,.18)}
.ccard .cbody{padding:22px 10px 0;align-items:center}
.ccard h3{font-size:30px;font-weight:500}
.imgcard img{border-radius:4px;height:auto;box-shadow:0 0 0 1px rgba(233,215,180,.5),0 0 0 10px rgba(233,215,180,.08),0 40px 90px rgba(0,0,0,.45)}
.sub-img img{border:0;border-radius:4px;height:auto;box-shadow:0 0 0 1px rgba(233,215,180,.55),0 0 0 10px rgba(233,215,180,.08),0 40px 90px rgba(0,0,0,.45)}

/* ---- occasions ---- */
.imgrow{align-items:center}
main .grid.imgrow img{aspect-ratio:auto;height:auto;object-fit:contain}
.ocard{border:0;border-radius:4px;background:var(--night)}
.ocard>img{aspect-ratio:auto;height:auto;width:100%}
.ocard .obody{padding:18px 22px 22px;background:var(--night);color:#FFFDF8}
.ocard h3{color:#FFFDF8;font-size:30px;font-weight:400;margin-bottom:2px}
.ocard p{color:rgba(255,253,248,.82);margin:0}

/* ---- how it works: a line with three large numerals (it is a sequence) ---- */
.step{background:none;border:0;border-top:1px solid var(--gold);border-radius:0;box-shadow:none;padding:26px 6px 0}
.step::before{position:static;display:block;width:auto;height:auto;background:none;border:0;border-radius:0;color:var(--gold-d);font-size:72px;font-weight:300;font-style:italic;line-height:.9;margin-bottom:12px}
.step h3{font-size:27px;font-weight:500}

/* ---- price list as a printed menu ---- */
.tbl-wrap{background:#fff;border:1px solid var(--gold-l);outline:1px solid var(--gold-l);outline-offset:7px;border-radius:2px;padding:8px 22px;margin-top:14px;margin-bottom:14px}
.ptable th{background:none;color:var(--gold-d);border-bottom:1px solid var(--gold)}
.ptable td:first-child{font-family:var(--serif);font-size:19px;font-weight:600;color:var(--plum)}

/* ---- why us: a ruled list, not boxes ---- */
.why ul{gap:0}
.why li{background:none;border:0;border-top:1px solid var(--gold-l);border-radius:0;box-shadow:none;padding:20px 4px}
.why li:last-child{border-bottom:1px solid var(--gold-l)}
.why li b{font-size:25px;font-weight:500}
.badge{border-radius:2px}
.card,.loc-card,.qcard{border-radius:6px}

/* ---- inner pages open in the evening too ---- */
.subhero{background:radial-gradient(ellipse at 84% 24%,rgba(201,166,107,.26),transparent 48%),radial-gradient(ellipse at 6% 96%,rgba(201,138,142,.16),transparent 42%),var(--night);color:#FFFDF8}
.subhero h1{color:#FFFDF8;font-weight:300;font-size:clamp(38px,4.6vw,68px);line-height:1}
.subhero .lead{color:rgba(255,253,248,.82)}
.subhero .ticks{color:rgba(255,253,248,.78)}
.subhero .ticks span::before{color:var(--candle)}
.subhero .crumb,.subhero a.crumb{color:var(--candle)}
.subhero [aria-current]{color:rgba(255,253,248,.7)}
.subhero p,.subhero li{color:rgba(255,253,248,.82)}
.b-hero .b-crumb{color:rgba(255,253,248,.7)}
.b-hero .b-crumb a{color:var(--candle)}

/* ---- the shop floor: what you can hire, with prices, like a store ---- */
#collection{padding-top:64px}
.shelf-label{font-family:var(--serif);font-size:28px;font-weight:500;color:var(--plum);margin:44px 0 16px;display:flex;align-items:baseline;gap:14px;border-bottom:1px solid var(--gold-l);padding-bottom:10px}
.shelf-label span{font-family:var(--sans);font-size:13px;color:var(--gold-d);font-weight:600}
.shelf{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px}
.prod{display:flex;flex-direction:column;position:relative;background:#fff;border:1px solid var(--line-soft);border-radius:4px;overflow:hidden;color:inherit;text-decoration:none;min-width:0;transition:transform .45s cubic-bezier(.2,.7,.2,1),box-shadow .45s,border-color .45s}
.prod>img{aspect-ratio:auto;height:auto;width:100%;display:block}
.prod .pi{display:flex;flex-direction:column;gap:3px;padding:16px 18px 18px;flex:1;background:#fff;position:relative}
.prod .pn{font-family:var(--serif);font-size:28px;font-weight:600;color:var(--plum);line-height:1.1}
.prod .pm{font-size:13px;color:var(--muted);line-height:1.45}
.prod .pp{display:flex;align-items:baseline;gap:8px;margin-top:10px;flex-wrap:wrap}
.prod .pp b{font-family:var(--serif);font-size:34px;font-weight:600;color:var(--plum);line-height:1}
.prod .pp span{font-size:12px;color:var(--muted)}
.prod .pb{margin-top:auto;display:block;text-align:center;padding:13px 10px;border:1px solid var(--plum);border-radius:2px;font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--plum);transition:background .3s,color .3s}
.prod .pp+.pb{margin-top:14px}
.prod .ptag{position:absolute;top:12px;left:12px;z-index:2;background:var(--night);color:var(--candle);font-size:11.5px;font-weight:600;padding:6px 11px;border-radius:2px}
.prod-own{background:var(--night);border-color:var(--night);justify-content:flex-end}
@media(min-width:1101px){.prod-own{grid-column:span 2}.prod-own .pn{font-size:40px;font-weight:400}.prod-own .pm{font-size:15px;max-width:420px}.prod-own .pb{align-self:flex-start;padding:15px 28px}}
.prod-own .pi{background:transparent}
.prod-own .pn,.prod-own .pp b{color:#FFFDF8}.prod-own .pm,.prod-own .pp span{color:rgba(255,253,248,.78)}
.prod-own .pb{border-color:var(--candle);color:var(--night);background:var(--candle)}
@media (hover:hover){.prod:hover{transform:translate3d(0,-8px,0);border-color:var(--gold-l);box-shadow:0 30px 60px rgba(46,34,51,.18),0 0 40px rgba(233,215,180,.5)}.prod:hover .pb{background:var(--plum);color:#fff}.prod-own:hover .pb{background:#fff;color:var(--night)}}
@media(max-width:1100px){.shelf{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:760px){.shelf{grid-template-columns:none;grid-auto-flow:column;grid-auto-columns:72%;overflow-x:auto;scroll-snap-type:x mandatory;gap:14px;padding-bottom:12px;-webkit-overflow-scrolling:touch}.prod{scroll-snap-align:start}.shelf-label{font-size:24px;margin-top:34px}}
.pshelf{grid-template-columns:repeat(auto-fill,minmax(88px,1fr));gap:10px}
.pshelf small{display:flex;justify-content:space-between;gap:6px;font-size:12.5px;margin-top:6px;color:var(--muted)}
.pshelf small b{font-family:var(--serif);font-size:17px;color:var(--plum)}
.spec{display:grid;grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr);gap:40px;align-items:center;margin-top:40px;padding:34px 38px;background:var(--night);color:#FFFDF8;border-radius:4px}
.spec-fig{position:relative;display:flex;justify-content:center;padding-right:54px}
.spec-fig img{max-height:300px;width:auto;height:auto;filter:drop-shadow(0 0 26px rgba(255,214,140,.55))}
.spec-fig .dim{position:absolute;right:0;top:4%;bottom:4%;border-left:1px solid var(--candle);border-top:1px solid var(--candle);border-bottom:1px solid var(--candle);width:12px;font-family:var(--serif);font-style:italic;font-size:20px;color:var(--candle);display:flex;align-items:center;white-space:nowrap;text-indent:20px}
.spec-fig .dim{width:auto;min-width:12px;padding-right:0;border-right:0}
.spec-t{font-family:var(--serif);font-size:34px;font-weight:400;margin:0 0 10px;color:#FFFDF8;line-height:1.05}
.spec ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 34px}
.spec li{display:grid;grid-template-columns:74px minmax(0,1fr);gap:12px;padding:12px 0;border-top:1px solid rgba(233,215,180,.28);font-size:14.5px;line-height:1.5}
.spec li b{font-family:var(--serif);font-style:italic;font-weight:500;font-size:18px;color:var(--candle)}
.spec li span{color:rgba(255,253,248,.86)}
@media(max-width:900px){.spec{grid-template-columns:1fr;padding:26px 22px;gap:22px}.spec ul{grid-template-columns:1fr}.spec-fig img{max-height:220px}}

/* ===== MOTION LAYER ===== */
@media (prefers-reduced-motion:no-preference){
@keyframes evZoom{from{transform:scale(1)}to{transform:scale(1.07) translate3d(-.6%,-.4%,0)}}
@keyframes evBokeh{0%{opacity:.25;transform:translate3d(0,6px,0) scale(1)}50%{opacity:.95}100%{opacity:.4;transform:translate3d(-14px,-10px,0) scale(1.06)}}
@keyframes evSweep{0%,58%{transform:translate3d(0,0,0) skewX(-14deg);opacity:0}62%{opacity:1}100%{transform:translate3d(620%,0,0) skewX(-14deg);opacity:0}}
@keyframes evLight{from{opacity:.3;filter:blur(14px) brightness(1.9);transform:translate3d(0,12px,0)}55%{opacity:1;filter:blur(2px) brightness(1.3)}to{opacity:1;filter:blur(0) brightness(1);transform:none}}
@keyframes evGlow{0%,100%{text-shadow:0 0 0 rgba(233,201,138,0)}50%{text-shadow:0 0 18px rgba(233,201,138,.85),0 0 42px rgba(233,201,138,.45)}}
@keyframes evPulse{0%,100%{box-shadow:0 14px 30px rgba(201,166,107,.35),0 0 0 0 rgba(217,185,120,.55)}55%{box-shadow:0 18px 40px rgba(201,166,107,.5),0 0 0 14px rgba(217,185,120,0)}}
@keyframes evSheen{0%,70%{transform:translate3d(-160%,0,0) skewX(-18deg)}100%{transform:translate3d(420%,0,0) skewX(-18deg)}}
@keyframes evFloat{0%,100%{transform:translate3d(0,0,0) rotate(0)}50%{transform:translate3d(0,-9px,0) rotate(.5deg)}}
@keyframes evFloatB{0%,100%{transform:translate3d(0,-4px,0) rotate(.35deg)}50%{transform:translate3d(0,6px,0) rotate(-.45deg)}}
@keyframes evTwinkle{0%,100%{opacity:1}50%{opacity:.22}}
@keyframes evRise{from{opacity:.3;transform:translate3d(0,38px,0) scale(.965) rotate(var(--ev-tilt,0deg))}to{opacity:1;transform:none}}
@keyframes evHead{from{opacity:.3;filter:blur(12px) brightness(1.8)}60%{opacity:1;filter:blur(1.5px) brightness(1.25)}to{opacity:1;filter:blur(0) brightness(1)}}
@keyframes evBulbOn{0%{filter:brightness(.82) saturate(.9)}40%{filter:brightness(1.18)}55%{filter:brightness(.95)}100%{filter:brightness(1.1) drop-shadow(0 0 10px rgba(255,214,140,.75))}}

/* home hero: the photo breathes, lights drift across it, a beam of light passes */
.hero{isolation:isolate}
.hero::before{z-index:1}
.hero-grid{z-index:2}
.hero-mobile{overflow:hidden;position:relative}
.hero-mobile::after{content:"";position:absolute;top:-10%;bottom:-10%;left:-45%;width:34%;background:linear-gradient(100deg,transparent,rgba(255,246,220,.5),transparent);animation:evSweep 7s ease-in-out infinite;pointer-events:none}
@media(min-width:981px){
.hero-grid::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;filter:blur(2.5px);animation:evBokeh 9s ease-in-out infinite alternate;
background:radial-gradient(circle at 58% 26%,rgba(255,236,190,.7) 0 .9%,transparent 2.3%),radial-gradient(circle at 71% 68%,rgba(255,244,214,.6) 0 .7%,transparent 2%),radial-gradient(circle at 84% 20%,rgba(255,226,170,.65) 0 1.1%,transparent 2.7%),radial-gradient(circle at 93% 74%,rgba(255,240,205,.55) 0 .8%,transparent 2.2%),radial-gradient(circle at 64% 84%,rgba(255,232,180,.5) 0 .9%,transparent 2.3%),radial-gradient(circle at 78% 40%,rgba(255,250,230,.5) 0 .5%,transparent 1.5%)}
.hero-grid::after{content:"";position:absolute;top:-25%;bottom:-25%;left:-30%;width:22%;z-index:-1;pointer-events:none;background:linear-gradient(100deg,transparent,rgba(255,246,220,.6),transparent);animation:evSweep 9s ease-in-out infinite}
}

/* hero words step out of a blur of light, one after another */
.hero .rv,.subhero .rv{animation:none}
.hero .rv>*,.subhero .rv>*{animation:evLight 1.15s cubic-bezier(.2,.7,.2,1) backwards}
.hero .rv>*:nth-child(2),.subhero .rv>*:nth-child(2){animation-delay:.12s}
.hero .rv>*:nth-child(3),.subhero .rv>*:nth-child(3){animation-delay:.26s}
.hero .rv>*:nth-child(4),.subhero .rv>*:nth-child(4){animation-delay:.4s}
.hero .rv>*:nth-child(n+5),.subhero .rv>*:nth-child(n+5){animation-delay:.54s}
.hero .script{animation:evLight 1.15s .26s cubic-bezier(.2,.7,.2,1) backwards,evGlow 4.2s 1.6s ease-in-out infinite}
.pill i{animation:evTwinkle 1.8s ease-in-out infinite}

/* inner-page hero photo floats */
.subhero .sub-img.rv{animation:evLight 1.2s .2s cubic-bezier(.2,.7,.2,1) backwards}
.sub-img img{animation:evFloat 7.5s ease-in-out infinite}

/* the main button: a glint runs across it, and in the hero it pulses */
.btn-gold{position:relative;overflow:hidden}
.btn-gold::after{content:"";position:absolute;top:-30%;bottom:-30%;left:0;width:34%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.75),transparent);animation:evSheen 4.8s ease-in-out infinite;pointer-events:none}
.hero .btn-gold,.subhero .btn-gold{animation:evPulse 2.9s ease-in-out infinite}

/* dividers become a row of bulbs that twinkle in turn */
.rule{height:14px;background:none;position:relative}
.rule::before,.rule::after{content:"";position:absolute;inset:0;background:radial-gradient(circle,#F7E4B4 0 2.2px,rgba(233,201,138,.55) 3.2px,transparent 6px) 0 50%/56px 14px repeat-x;animation:evTwinkle 1.7s ease-in-out infinite}
.rule::after{background-position:28px 50%;animation-delay:-.85s}
.zone-plum{position:relative}
.zone-plum::before,.zone-plum::after{content:"";position:absolute;left:0;right:0;height:14px;background:radial-gradient(circle,#F7E4B4 0 2.2px,rgba(233,201,138,.5) 3.2px,transparent 6px) 0 50%/44px 14px repeat-x;animation:evTwinkle 1.5s ease-in-out infinite;pointer-events:none}
.zone-plum::before{top:10px}.zone-plum::after{bottom:10px;background-position:22px 50%;animation-delay:-.75s}

/* figures glow in turn */
.glance b,.badge b{animation:evGlow 3.8s ease-in-out infinite}
.glance div:nth-child(2) b{animation-delay:.5s}.glance div:nth-child(3) b{animation-delay:1s}.glance div:nth-child(4) b{animation-delay:1.5s}.glance div:nth-child(5) b{animation-delay:2s}

/* photos drift gently on their own */
.imgcard img,.rv>img{animation:evFloat 8s ease-in-out infinite}
.imgrow>:nth-child(odd) img,.imgrow>img:nth-child(odd){animation:evFloat 8.5s ease-in-out infinite}
.imgrow>:nth-child(even) img,.imgrow>img:nth-child(even){animation:evFloatB 9.5s ease-in-out infinite}

/* pointer devices: cards lift, tilt and light up; the photo inside moves */
@media (hover:hover){
.ocard,.ccard,.imgcard,.loc-card,.card,.step,.why li{transition:transform .5s cubic-bezier(.2,.7,.2,1),box-shadow .5s,border-color .5s}
.ocard:hover,.ccard:hover{transform:translate3d(0,-10px,0) rotate(-1.3deg);box-shadow:0 30px 64px rgba(46,34,51,.22),0 0 0 1px var(--gold-l),0 0 46px rgba(233,215,180,.6)}
.grid>:nth-child(even).ocard:hover,.grid>:nth-child(even).ccard:hover{transform:translate3d(0,-10px,0) rotate(1.3deg)}
.ocard>img,.ccard img{transition:filter .6s}
.ocard:hover>img,.ccard:hover img{filter:brightness(1.07) saturate(1.1)}
.imgcard:hover img,.rv>img:hover,.imgrow img:hover,.sub-img img:hover{animation-play-state:paused;filter:brightness(1.06) saturate(1.08)}
.imgrow img,.rv>img,.sub-img img{transition:filter .5s,box-shadow .5s,rotate .6s cubic-bezier(.2,.7,.2,1),scale .6s cubic-bezier(.2,.7,.2,1)}
.imgrow img:hover,.rv>img:hover,.sub-img img:hover{rotate:-1.4deg;scale:1.035;box-shadow:0 30px 60px rgba(46,34,51,.24),0 0 44px rgba(233,215,180,.6)}
.imgrow>:nth-child(even) img:hover,.imgrow>img:nth-child(even):hover{rotate:1.4deg}
.loc-card:hover{transform:translate3d(0,-6px,0) rotate(-.8deg);border-color:var(--gold-l);box-shadow:0 0 40px rgba(233,201,138,.28)}
.card:hover,.step:hover,.why li:hover{transform:translate3d(0,-6px,0);box-shadow:0 22px 48px rgba(46,34,51,.16),0 0 0 1px var(--gold-l)}
.piece-grid .item .mq{transition:transform .45s cubic-bezier(.2,.7,.2,1),box-shadow .45s}
.piece-grid .item:hover .mq{transform:translate3d(0,-6px,0) rotate(-3deg) scale(1.08);box-shadow:0 0 0 3px #FDFBF8,0 0 0 4px var(--gold-l),0 16px 30px rgba(46,34,51,.2),0 0 30px rgba(255,214,140,.7)}
.piece-grid .item:nth-child(even):hover .mq{transform:translate3d(0,-6px,0) rotate(3deg) scale(1.08)}
.piece-grid .item:hover .mq img{animation:evBulbOn .7s ease-out forwards}
.chip{transition:transform .25s,box-shadow .25s,border-color .25s}
.chip:hover{transform:translate3d(0,-2px,0);box-shadow:0 8px 18px rgba(201,166,107,.3)}
}

/* as you scroll: headings come out of a blur of light, cards rise into place */
@supports (animation-timeline:view()){
main .rv{animation:none}
.hero .rv>*,.subhero .rv>*{animation:evLight 1.15s cubic-bezier(.2,.7,.2,1) backwards}
main section:not(.hero):not(.subhero) h2,main section:not(.hero):not(.subhero) .eyebrow{animation:evHead linear backwards;animation-timeline:view();animation-range:entry 5% cover 28%}
.ocard,.ccard,.step,.glance,.imgcard,.why li,.loc-card,.card,.imgrow>*,.ptable,.badge{animation:evRise linear backwards;animation-timeline:view();animation-range:entry 0% cover 24%}
.grid>:nth-child(3n+1),.imgrow>:nth-child(odd){--ev-tilt:-2deg}
.grid>:nth-child(3n),.imgrow>:nth-child(even){--ev-tilt:2deg}
}
}
.steps .step p.step-t{font-family:var(--serif);font-size:21px;line-height:1.25;color:var(--plum);margin:4px 0 8px;font-weight:600}.imgrow img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:14px;box-shadow:var(--shadow-sm);display:block}.mapcap{font-size:13.5px;color:var(--muted);margin:12px 0 0;max-width:820px}.why li h3{font-family:var(--sans);font-size:14.5px;font-weight:700;letter-spacing:0;margin:0 0 2px;color:var(--plum)}.glance p a.ilink{font-weight:600}.card p.ct{font-family:var(--serif);font-size:20px;line-height:1.25;color:var(--plum);font-weight:600;margin:0 0 6px}.note-s{margin-top:12px;color:var(--muted);font-size:13px}.grid.g2+.grid.g2,.prose+.grid,.grid+.prose{margin-top:22px}
section.subhero.b-hero{padding-top:0;padding-bottom:0}.b-hero .wrap{padding-top:26px;padding-bottom:16px;text-align:left}.b-hero h1{font-size:clamp(30px,3.4vw,46px);margin-bottom:8px}.b-hero .lead{margin:0;max-width:940px;font-size:16px}.b-hero .b-crumb{font-size:11px;letter-spacing:.2em;text-transform:uppercase;font-weight:600;margin-bottom:10px}
section.b-sec{background:var(--night);color:#FFFDF8;padding-top:10px;padding-bottom:84px;color-scheme:dark}
.b-sec h2,.b-sec h3{animation:none!important}
.b-sec a.ilink{color:var(--candle)}
.bld{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:28px;align-items:start}.bld>*{min-width:0}
.b-main{display:grid;gap:14px;grid-template-columns:minmax(0,1fr)}.b-main>*{min-width:0}
.b-pan{background:rgba(255,253,248,.035);border:1px solid rgba(233,215,180,.16);border-radius:6px;padding:22px 24px;min-width:0}
.b-sec .b-pan h2{font-size:24px;margin:0 0 8px;color:#FFFDF8}
.b-pan p{font-size:14.5px;color:rgba(255,253,248,.74);margin:0 0 10px}
.bld .b-live{display:none}.bld.js .b-live{display:block}.bld.js .b-static{display:none}
.b-lbl{display:block;font-size:12.5px;font-weight:600;color:rgba(255,253,248,.7);margin:14px 0 6px}
.bld button{font-family:var(--sans)}
.bld :focus-visible{outline:2px solid var(--candle);outline-offset:2px}

/* with the script on, the two top panels dissolve into one ordered console: heading, typing bar, stage, favourites, backdrop, tray */
.bld.js .b-type,.bld.js .b-type>.b-live,.bld.js .b-see,.bld.js .b-see>.b-live{display:contents}
.bld.js .b-type>h2{order:1;margin:0;font-size:24px}.bld.js .b-field{order:2}.bld.js .b-stage{order:3}.bld.js .b-presets{order:4;margin-top:0}
.bld.js .b-see>h2{order:5;margin:10px 0 -4px;font-size:20px}.bld.js .b-ctl{order:6;margin-top:0}
.bld.js .b-traylbl{order:7}.bld.js .b-type>p{order:8;margin:-6px 0 0;font-size:13.5px}.bld.js .b-tray{order:9}.bld.js #b-inv{order:10;margin-top:0!important}.bld.js .b-optpan{order:11;margin-top:10px}
.bld.js .b-lbl[for=b-word]{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}

/* typing bar */
