.b-stage[data-scene=fairy] .b-scene{background:linear-gradient(180deg,transparent 78%,#2a2030 78%,#120c17 100%),linear-gradient(180deg,#2a2030,#3a2c3f 78%)}
.b-stage[data-scene=fairy] .b-scene::after{opacity:1;inset:0 0 22% 0;background:radial-gradient(circle,rgba(255,240,200,1) 0,rgba(255,240,200,1) 1.1px,rgba(255,214,140,.4) 2.6px,transparent 4.4px) 0 0/26px 34px,radial-gradient(circle,rgba(255,240,200,.9) 0,rgba(255,240,200,.9) 1px,rgba(255,214,140,.32) 2.4px,transparent 4px) 13px 17px/26px 34px;-webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}
