.b-shade{background:radial-gradient(95% 85% at 50% 62%,rgba(12,8,15,.5),rgba(12,8,15,.94));opacity:var(--dim);transition:opacity .25s}
.b-rows{position:absolute;left:4%;right:4%;bottom:22%;display:flex;justify-content:center;align-items:flex-end;z-index:2}
.b-stage[data-scene=photo] .b-rows{bottom:17%;bottom:9.56cqw}
.b-line{flex:0 0 auto;display:flex;align-items:flex-end;gap:calc(var(--p)*.34);--p:60px}
.b-set{position:relative;flex:0 0 auto}
.b-set::before{content:"";position:absolute;left:-12%;right:-12%;top:-45%;bottom:-25%;background:radial-gradient(50% 50% at 50% 55%,rgba(255,206,140,calc(.08 + var(--dim)*.3)),transparent 70%);z-index:-1;pointer-events:none}
.b-set::after{content:"";position:absolute;left:-5%;right:-5%;top:88%;height:calc(var(--p)*.5);background:radial-gradient(50% 50% at 50% 50%,rgba(255,200,130,calc(.12 + var(--dim)*.42)),transparent 72%);filter:blur(5px);z-index:-1;pointer-events:none}
.b-row,.b-refl{display:flex;gap:calc(var(--p)*.07);flex-wrap:nowrap}
.b-row{align-items:flex-end}
.b-mq{height:var(--p);flex:0 0 auto}
.b-mq img{height:100%;width:auto;max-width:none;display:block;filter:sepia(.22) saturate(1.25) brightness(1.04) drop-shadow(0 0 calc(var(--p)*.04) rgba(255,226,170,calc(.3 + var(--dim)*.5))) drop-shadow(0 0 calc(var(--p)*.2) rgba(255,186,104,calc(var(--dim)*.6)))}
