@keyframes bOn{0%{opacity:0;transform:translateY(-10%);filter:brightness(.2)}22%{opacity:1;transform:none;filter:brightness(.28)}40%{filter:brightness(1.25)}52%{filter:brightness(.5)}68%{filter:brightness(1.3)}100%{opacity:1;transform:none;filter:brightness(1)}}
.b-refl{position:absolute;left:0;top:100%;height:var(--p);transform:scaleY(-1);opacity:.22;filter:blur(1.2px);pointer-events:none;-webkit-mask-image:linear-gradient(0deg,#000,transparent 62%);mask-image:linear-gradient(0deg,#000,transparent 62%)}
.b-stage[data-scene=photo] .b-refl{opacity:.1}
.b-refl .b-mq.new{animation-name:bFade}
@keyframes bFade{from{opacity:0}to{opacity:1}}
.b-ruler{position:absolute;left:0;right:0;top:calc(100% + var(--p)*.2 + 4px);height:1px;background:rgba(247,228,180,.6)}
.b-ruler::before,.b-ruler::after{content:"";position:absolute;top:-4px;width:1px;height:9px;background:rgba(247,228,180,.8)}.b-ruler::before{left:0}.b-ruler::after{right:0}
