@container (max-width:520px){.b-hm,.b-person span{display:none}}
.b-empty{position:absolute;left:50%;top:46%;transform:translate(-50%,-50%);width:82%;text-align:center;font-family:var(--serif);font-style:italic;font-size:clamp(16px,3cqw,27px);color:rgba(247,228,180,.9);z-index:2}
