.b-stat{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:12px;color:rgba(255,253,248,.72);text-shadow:0 1px 6px rgba(0,0,0,.8)}.b-stat b{color:#FFFDF8;font-weight:600}
.b-pricechip[hidden],.b-save[hidden]{display:none!important}
.b-pricechip{display:none;pointer-events:auto;flex:0 0 auto;border:0;border-radius:999px;background:var(--candle);color:var(--night);font-size:12.5px;font-weight:700;padding:8px 13px;cursor:pointer;box-shadow:0 6px 18px rgba(0,0,0,.4)}

/* stage controls */
.b-ctl{display:flex;flex-wrap:wrap;gap:12px 22px;align-items:center;margin-top:16px}
.b-scenes{display:flex;flex-wrap:wrap;gap:8px}
.b-scn{display:inline-flex;align-items:center;gap:8px;min-height:40px;padding:5px 14px 5px 7px;border-radius:999px;border:1px solid rgba(233,215,180,.25);background:transparent;color:rgba(255,253,248,.82);font-size:13px;font-weight:500;cursor:pointer}
