.b-scn[data-scene=studio] i{background:radial-gradient(circle at 50% 70%,#8a6470,#2a1f30)}.b-scn[data-scene=candle] i{background:radial-gradient(circle at 35% 40%,#ffc878 0,#ffc878 14%,transparent 30%),radial-gradient(circle at 70% 60%,#ffb86a 0,#ffb86a 10%,transparent 26%),#3a2416}
.b-scn[data-scene=fairy] i{background:radial-gradient(circle,#fff0c8 0,#fff0c8 1px,transparent 2.4px) 0 0/7px 8px,#2a2030}.b-scn[data-scene=photo] i{background:#c9a56b var(--photo) 60% 80%/260% no-repeat}
.b-scn:hover{border-color:rgba(247,228,180,.6)}.b-scn[aria-pressed=true]{border-color:var(--candle);color:var(--candle);background:rgba(247,228,180,.09)}
