.b-tog{display:flex;align-items:center;gap:8px;font-size:13px;color:rgba(255,253,248,.82);cursor:pointer;min-height:32px}.b-tog input{width:18px;height:18px;accent-color:#E9D7B4}
.b-note{font-size:12.5px!important;margin:14px 0 0!important}.b-note.warn{color:#F0B5BA!important;font-weight:600}

/* the tray of real pieces */
.b-traylbl{font-family:var(--serif);font-style:italic;font-size:17.5px!important;color:rgba(255,253,248,.88)!important;margin:12px 0 0!important}
