.b-tgroup{display:grid;grid-template-columns:repeat(auto-fill,minmax(46px,1fr));gap:6px}
.b-key{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;min-height:64px;min-width:0;padding:9px 2px 8px;border-radius:4px;border:1px solid rgba(233,215,180,.14);background:rgba(12,8,15,.5);color:rgba(255,253,248,.82);cursor:pointer;transition:transform .15s,border-color .15s,background .15s}
.b-key img{height:30px;width:auto;max-width:100%;display:block;filter:sepia(.22) saturate(1.25) drop-shadow(0 0 5px rgba(255,205,140,.5))}
.b-key:hover{border-color:var(--candle);background:rgba(247,228,180,.06)}.b-key:active{transform:scale(.93)}
.b-st{display:flex;gap:4px}.b-st i{width:5px;height:5px;border-radius:50%;background:var(--candle);box-shadow:0 0 6px rgba(255,214,140,.95)}
.b-key[data-used="1"] .b-st i:last-child,.b-key[data-used="2"] .b-st i,.b-key[data-used="3"] .b-st i{background:rgba(255,253,248,.2);box-shadow:none}
.b-key[data-used="2"] img,.b-key[data-used="3"] img{opacity:.42}.b-key[data-used="3"]{border-color:#E09AA0}
.b-key.util{grid-column:span 2;font-size:12.5px;font-weight:600;min-height:64px}

/* delivery zone and hire length */
.b-grid2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}.b-grid2>*{min-width:0}@media(max-width:520px){.b-grid2{grid-template-columns:minmax(0,1fr)}}
.bld input[type=date],.bld select{width:100%;min-width:0;padding:13px 14px;border:1px solid rgba(233,215,180,.3);border-radius:4px;background:rgba(12,8,15,.55);font:inherit;font-size:16px;color:#FFFDF8}
.b-opts{display:flex;gap:8px;flex-wrap:wrap}
.b-opt{position:relative;flex:1;min-width:130px;border:1px solid rgba(233,215,180,.22);border-radius:4px;padding:12px 14px;cursor:pointer;background:rgba(12,8,15,.4);font-size:13px}
.b-opt b{display:block;font-size:13.5px;color:#FFFDF8}.b-opt span{color:rgba(255,253,248,.62);font-size:12.5px}.b-opt.on{border-color:var(--candle);background:rgba(247,228,180,.1)}.b-opt input{position:absolute;opacity:0;pointer-events:none}
.b-opt:focus-within{outline:2px solid var(--candle);outline-offset:2px}
.b-ztab{font-size:13.5px;width:100%;border-collapse:collapse;color:#FFFDF8}.b-ztab td{padding:7px 0;border-bottom:1px dashed rgba(233,215,180,.2);vertical-align:top}.b-ztab td:last-child{text-align:right;font-weight:600;white-space:nowrap;padding-left:12px}.b-ztab small{display:block;color:rgba(255,253,248,.62);font-size:12px}
.b-ex img{width:100%;height:auto;border-radius:4px;display:block}

/* the price ticket */
.b-side{position:sticky;top:calc(var(--b-hdr,176px) + 16px)}
.b-ticket{position:relative;background:#FBF6EA;color:var(--ink);border-radius:6px;color-scheme:light;box-shadow:0 30px 80px rgba(0,0,0,.5)}
.b-tk-top{padding:24px 24px 20px}
