.b-lines li span:last-child{font-weight:600;white-space:nowrap}.b-lines li.disc span{color:var(--rose-d)}
.b-total{display:flex;justify-content:space-between;align-items:baseline;margin:16px 0 2px}.b-total b{font-family:var(--serif);font-size:54px;color:var(--plum);font-weight:500;line-height:1;font-variant-numeric:tabular-nums}.b-total span{font-size:13px;color:var(--muted);font-weight:600}
.b-dep{font-size:13px!important;margin:10px 0 0!important}.b-dep b{color:var(--gold-d)}
.b-quote .btn{width:100%;margin-top:6px}.b-quote button.btn{font-family:var(--sans)}
.b-fine{font-size:12px!important;color:var(--taupe)!important;text-align:center;margin:12px 0 0!important}
.b-sum{margin-top:12px;font-size:12px;color:var(--muted);background:#fff;border-radius:4px;padding:12px;white-space:pre-wrap;font-family:var(--sans);overflow-wrap:anywhere}
.b-how{margin:48px 0 0;padding-top:30px;border-top:1px solid rgba(233,215,180,.2)}.b-sec .b-how h3{font-size:24px;color:#FFFDF8}.b-how p{font-size:15.5px;color:rgba(255,253,248,.82);margin:0 0 10px;max-width:820px}

/* one column: on an upright phone or tablet the stage stays in view under the header while you choose pieces */
@media(max-width:1020px){
.bld{grid-template-columns:minmax(0,1fr)}.b-side{position:static}
.b-pricechip{display:block}
.bld.js .b-stage{aspect-ratio:2/1;max-height:36vh;width:100%}
}
@media(max-width:1020px) and (min-height:560px) and (orientation:portrait){.bld.js .b-stage{position:sticky;top:var(--b-hdr,113px);z-index:6;box-shadow:0 0 0 1px rgba(233,215,180,.3),0 18px 40px rgba(0,0,0,.6)}}
/* wide screens: the stage also stays in view under the header, so every piece you tap is seen landing */
@media(min-width:1021px) and (min-height:520px){.bld.js .b-stage{position:sticky;top:var(--b-hdr,176px);z-index:6;width:100%;max-height:clamp(150px,calc(100vh - var(--b-hdr,176px) - 310px),285px);box-shadow:0 0 0 1px rgba(233,215,180,.3),0 22px 50px rgba(0,0,0,.65)}.b-key{min-height:58px}.b-key.util{min-height:58px}}
@media(max-width:520px){.b-hero h1{font-size:30px}.b-hero .lead{font-size:15px}.b-pan{padding:18px 16px}.b-tray{padding:10px}.b-tk-top,.b-tk-stub{padding-left:18px;padding-right:18px}.b-stat{font-size:11px;gap:2px 10px}.b-tgroup{grid-template-columns:repeat(7,minmax(0,1fr));gap:5px}.b-key{min-height:58px}.b-key.util{grid-column:span 1;font-size:11.5px;min-height:58px}.b-total b{font-size:46px}}
@media(prefers-reduced-motion:reduce){.b-mq.new{animation:none}}
.legal{max-width:800px;margin:0 auto}.legal h2{font-size:30px;margin:38px 0 12px}.legal h2:first-child{margin-top:0}.legal p,.legal li{font-size:15.5px;line-height:1.75;color:var(--ink)}.legal ul{padding-left:20px;margin:0 0 1em}.legal li{margin-bottom:6px}.fgroup .faq{margin-top:6px}.fgroup .sec-head{margin-bottom:22px}.fgroup .sec-head p{font-size:15.5px;color:var(--muted);margin:10px 0 0}section.fgroup{padding:56px 0}.qnote{font-size:14px;line-height:1.55;color:var(--ink);background:var(--champ);border-left:3px solid var(--gold);border-radius:4px;padding:14px 16px;margin:0 0 16px}.qnote[hidden]{display:none}.qnote strong{display:block;font-family:var(--serif);font-size:21px;font-weight:600;color:var(--plum);margin-bottom:2px}.qnote span{display:block}.qnote span+span{margin-top:6px;color:var(--muted);font-size:13px}.enq .contact{margin-top:18px;color:var(--muted);font-size:15px}
